def transform(grid):
    """Return a 3x3 tile of the color of the largest monochrome component."""
    h, w = len(grid), len(grid[0])
    seen = set()
    best_color = None
    best_size = -1
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            size = 0
            while q:
                y, x = q.popleft()
                size += 1
                for ny, nx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            if size > best_size:
                best_color, best_size = color, size
    return [[best_color] * 3 for _ in range(3)]


